sp_widget.client_script:
api.controller = function($location) {
    var c = this;

    /*
     * Navigate to the Learning Application catalog item.
     */
    c.goToEmployee = function() {
        $location.url(
            "?id=sc_cat_item&sys_id=40382a6a478e8310ff78de94116d435e"
        );
    };

    /*
     * Navigate to the employee's learning records.
     */
    c.goToRecords = function() {
        $location.url("?id=check_my_records_asean");
    };

    /*
     * Navigate to the Pending Actions page.
     */
    c.goToPendingActions = function() {
        $location.url("?id=pending_actions_asean");
    };

    /*
     * Return to the Role Selection page.
     */
    c.goBack = function() {
        $location.url("?id=role_selection_asean");
    };

    /*
     * Keyboard accessibility.
     * Enter or Space activates the selected tile.
     */
    c.handleTileKey = function(event, tileType) {
        var keyCode = event.which || event.keyCode;

        if (keyCode !== 13 && keyCode !== 32) {
            return;
        }

        event.preventDefault();

        if (tileType === "application") {
            c.goToEmployee();
        } else if (tileType === "records") {
            c.goToRecords();
        } else if (tileType === "pending") {
            c.goToPendingActions();
        }
    };
};

sp_widget.css:
.learning-home {
  position: relative;
  min-height: 620px;
  padding: 55px 70px 80px;
  background-color: #ffffff;
  box-sizing: border-box;
}

.page-heading {
  margin-bottom: 70px;
  text-align: center;
}

.page-heading h2 {
  margin: 0;
  color: #333333;
  font-size: 28px;
  font-weight: 600;
}

.heading-line {
  width: 65px;
  height: 3px;
  margin: 15px auto 0;
  background-color: #f58220;
  border-radius: 3px;
}

.menu {
  display: flex;
  justify-content: center;
  align-items: stretch;
  gap: 55px;
  flex-wrap: wrap;
}

.tile {
  width: 240px;
  min-height: 210px;
  padding: 35px 25px;
  text-align: center;
  cursor: pointer;
  background-color: #ffffff;
  border: 1px solid #e4e4e4;
  border-radius: 10px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
  box-sizing: border-box;
  outline: none;
}

.tile:hover,
.tile:focus {
  transform: translateY(-6px);
  border-color: #f58220;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.14);
}

.icon-container {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 85px;
  height: 85px;
  margin: 0 auto 25px;
  background-color: #fff3e8;
  border-radius: 50%;
  transition:
    background-color 0.25s ease,
    transform 0.25s ease;
}

.tile:hover .icon-container,
.tile:focus .icon-container {
  background-color: #f58220;
  transform: scale(1.05);
}

.icon-container i {
  color: #f58220;
  font-size: 43px;
  transition: color 0.25s ease;
}

.tile:hover .icon-container i,
.tile:focus .icon-container i {
  color: #ffffff;
}

.tile-label {
  color: #f58220;
  font-size: 17px;
  font-weight: 600;
  line-height: 1.4;
}

.back-section {
  position: absolute;
  left: 35px;
  bottom: 25px;
}

.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #333333;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  outline: none;
}

.back-btn:hover,
.back-btn:focus {
  color: #f58220;
  text-decoration: none;
}

.back-icon {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 38px;
  height: 38px;
  color: #ffffff;
  background-color: #f58220;
  border-radius: 50%;
  transition:
    background-color 0.2s ease,
    transform 0.2s ease;
}

.back-icon i {
  font-size: 16px;
}

.back-btn:hover .back-icon,
.back-btn:focus .back-icon {
  background-color: #d96d0d;
  transform: translateX(-3px);
}

.back-text {
  line-height: 38px;
}

@media screen and (max-width: 900px) {

  .learning-home {
    padding: 40px 25px 90px;
  }

  .page-heading {
    margin-bottom: 45px;
  }

  .menu {
    gap: 25px;
  }

  .tile {
    width: 220px;
  }

  .back-section {
    left: 20px;
    bottom: 20px;
  }
}

@media screen and (max-width: 760px) {

  .menu {
    gap: 20px;
  }

  .tile {
    width: calc(50% - 15px);
    min-width: 210px;
  }
}

@media screen and (max-width: 520px) {

  .learning-home {
    min-height: 100vh;
    padding: 35px 20px 90px;
  }

  .page-heading h2 {
    font-size: 23px;
  }

  .menu {
    flex-direction: column;
    align-items: center;
  }

  .tile {
    width: 100%;
    max-width: 300px;
    min-width: 0;
  }
}

sp_widget.script:
(function() {
    /*
     * No server-side processing is currently required
     * for this navigation widget.
     */

    data.userName = gs.getUserDisplayName() || "";
    data.userEmail = gs.getUser().getEmail() || "";
    data.userUserName = gs.getUserName() || "";
})();
